  final Handler main=new Handler(Looper.getMainLooper());
  final ArrayList<Item> songs=new ArrayList<>(),items=new ArrayList<>();
  final android.util.LruCache<String,Bitmap> thumbs=new android.util.LruCache<String,Bitmap>(24*1024*1024){protected int sizeOf(String k,Bitmap b){return b.getByteCount();}};
  final Set<String> pending=new HashSet<>(),failed=new HashSet<>();
